import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CDU0sSpB.js";const _=JSON.parse('{"title":"任务与持久执行","description":"Hearth 如何把意图变成可恢复、可验证、带预算和证据的长期任务。","frontmatter":{"title":"任务与持久执行","description":"Hearth 如何把意图变成可恢复、可验证、带预算和证据的长期任务。","outline":false},"headers":[],"relativePath":"design/tasks.md","filePath":"design/tasks.md","lastUpdated":1793863446000}'),s={name:"design/tasks.md"};function o(n,t,h,i,p,l){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="任务与持久执行" tabindex="-1">任务与持久执行 <a class="header-anchor" href="#任务与持久执行" aria-label="Permalink to &quot;任务与持久执行&quot;">​</a></h1><p class="lead">Hearth 不把一次请求当成一段临时对话，而是把它变成可以跨重启、休眠和网络中断继续存在的任务。用户看到的是目标和进度，系统保存的是工作单元、执行尝试、证据和恢复路径。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><p>一个任务要有清楚的目标、验收方式、截止时间、预算和取消入口。任务可以被拆成多个工作单元，每个工作单元只允许一个执行者推进；每次实际尝试都要留下输入、结果、产物、失败原因和是否可以继续的记录。</p><p>目标不是任务标题里的一句话，而是独立保存的契约。验收条件、证据要求、预算、截止时间、停止条件和复核策略随目标一起保存；调度器在关闭目标型任务前生成完成报告，缺少证据时只能保持等待、受阻或转人工。完整边界见<a href="/hearth-os/design/goals-and-evidence.html">目标、完成判定与证据</a>。</p><p>任务状态必须对用户诚实。排队、执行、等待审批、等待输入、重试、失败、暂停和完成是不同的状态，不能用一句“处理中”全部覆盖。用户要能看到为什么停、停了多久、接下来会发生什么，以及是否需要自己介入。</p><p>持久执行要覆盖真实故障：服务重启、电脑休眠、网络断开、执行器崩溃、外部服务超时、设备离线和版本升级。恢复后系统要重新确认目标和当前状态，不信任旧的自然语言“已完成”，也不在没有核对的情况下重复产生外部副作用。</p><p>任务图用于表达依赖、并行、汇合、补偿和人工节点。第一阶段不追求完整的工作流平台，只实现能支撑真实任务的顺序、并行、等待和恢复，避免为了架构完整性引入难以维护的重型引擎。</p><h2 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to &quot;设计取舍&quot;">​</a></h2><p>任务、工作单元、执行尝试和产物分开保存。任务描述用户要的结果，工作单元描述被授权的一小段工作，执行尝试描述某一次实际运行，产物和回执描述真正交付了什么。把它们混成一个对象，会让重试、预算和审计都变得混乱。</p><p>事实记录优先于内存状态。每次状态变化都先写入本地记录，再更新界面和通知；界面只做投影，崩溃后可以从记录重建。早期采用单进程、单写者和本地数据库，用明确的定时器、待办队列和检查点完成恢复，不提前拆微服务。</p><table tabindex="0"><thead><tr><th>取舍</th><th>Hearth 的选择</th><th>代价与控制</th></tr></thead><tbody><tr><td>工作流实现</td><td>显式状态机和简单任务图</td><td>复杂流程需要手工建模，但行为容易验证和恢复</td></tr><tr><td>执行权</td><td>同一工作单元只有一个有效执行者</td><td>需要租约和过期回收，但能避免两个执行器同时写入</td></tr><tr><td>失败处理</td><td>先验证，再决定重试、换执行器或转人工</td><td>恢复路径更多，但不会用盲目重试制造重复副作用</td></tr><tr><td>长任务</td><td>保存检查点和中间产物</td><td>需要更多存储和清理规则，但休眠和重启后可以继续</td></tr><tr><td>预算</td><td>每级都有硬上限和取消路径</td><td>任务可能需要用户追加预算，但不会静默透支</td></tr><tr><td>外部结果不确定</td><td>先对账，不直接重试</td><td>需要人工或连接器核对，但能避免重复发送或重复写入</td></tr></tbody></table><p>旧执行者的结果不能覆盖新状态。工作单元被重新分配后，之前执行者提交的迟到结果只能作为证据保留，不能直接推进任务；需要合并时由当前执行路径重新验证。</p><p>恢复不是简单重跑。进程崩溃后从检查点继续，网络中断后保留待发动作并按同一标识重投，执行器超时后保存工作区并判断是否换执行方式，设备离线时进入设备队列，外部结果不确定时进入核对状态。每种恢复都要给用户一个可理解的原因和下一步。</p>',14)])])}const f=a(s,[["render",o]]);export{_ as __pageData,f as default};
